    ADD CONSTRAINT no_overlapping_confirmed_bookings EXCLUDE USING gist (court_id WITH =, tsrange((booking_date + start_time), (booking_date + end_time), '[)'::text) WITH &&) WHERE ((status = 'CONFIRMED'::public.booking_status));


